package java.util;
public class ArrayList<E> extends AbstractList<E> implements RandomAccess,Cloneable,java.io.Serializable { private Object[] data;private int count; public ArrayList(){data=new Object[0];} public ArrayList(int n){if(n<0)throw new IllegalArgumentException();data=new Object[n];} public ArrayList(Collection<? extends E> c){data=c.toArray();count=data.length;} public int size(){return count;} private void range(int i){if(i<0||i>=count)throw new IndexOutOfBoundsException();} public E get(int i){range(i);return (E)data[i];} public E set(int i,E e){range(i);E old=(E)data[i];data[i]=e;return old;} public void ensureCapacity(int n){if(n>data.length){int k=Math.max(n,Math.max(10,data.length+(data.length>>1)));Object[] a=new Object[k];System.arraycopy(data,0,a,0,count);data=a;}} public void trimToSize(){if(count<data.length){Object[] a=new Object[count];System.arraycopy(data,0,a,0,count);data=a;}} public void add(int i,E e){if(i<0||i>count)throw new IndexOutOfBoundsException();ensureCapacity(count+1);System.arraycopy(data,i,data,i+1,count-i);data[i]=e;count++;modCount++;} public E remove(int i){range(i);E e=(E)data[i];System.arraycopy(data,i+1,data,i,count-i-1);data[--count]=null;modCount++;return e;} public void clear(){for(int i=0;i<count;i++)data[i]=null;count=0;modCount++;} }
